  'sup.self.title': `Pirmiausia pabandykite patys`,
  'sup.self.body': `Į daugumą klausimų atsakoma <a href="manual.html#trouble">problemų sprendimo skyriuje</a>, <a href="faq.html">DUK</a> ir programos įtaisytoje pagalboje („Pagalba“ šoniniame meniu).`,
  'nav.roadmap': `Planas`,
